const getEmpBankDetailsSC = async (req, res) => {
  const { EmployeeId, Account_NO, AccountHolderName, bankName, Name, branchName, IFSC_Code, company_code, Location_Code } = req.body;

  try {
    // Connect to the database
    const pool = await connection.connectToDatabase();

    // Execute the query
    const result = await pool
      .request()
      .input("mode", sql.NVarChar, "ESC")
      .input("EmployeeId", sql.NVarChar, EmployeeId)
      .input("Account_NO", sql.NVarChar, Account_NO)
      .input("AccountHolderName", sql.NVarChar, AccountHolderName)
      .input("bankName", sql.NVarChar, bankName)
      .input("company_code", sql.NVarChar, company_code)
      .input("Location_Code", sql.NVarChar, Location_Code)
      .input("Name", sql.NVarChar, Name)
      .input("branchName", sql.NVarChar, branchName)
      .input("IFSC_Code", sql.NVarChar, IFSC_Code)
      .query(`EXEC sp_employee_bankdetails @mode,@Account_NO,@EmployeeId,'',@Name,@AccountHolderName,@bankName,@branchName,@IFSC_Code,'',@company_code,@Location_Code,0,'','','','','','','','','','','','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL`);

    // Send response
    if (result.recordset.length > 0) {
      res.status(200).json(result.recordset); // 200 OK if data is found
    } else {
      res.status(404).send("Data not found"); // 404 Not Found if no data is found
    }
  } catch (err) {
    console.error(err);
    res.status(500).send({ message: err.message || "Internal Server Error" });
  }
};
