const deleteFinacnialyearlockscreen = async (req, res) => {
  const keyfieldToDelete = req.body.keyfield;

  const pool = await connection.connectToDatabase();
  for (const keyfield of keyfieldToDelete) {
    try {
      await pool
        .request()

        .input("mode", sql.NVarChar, "D")
        .input("keyfield", sql.NVarChar, keyfield)
        .query(
          `EXEC sp_financial_year_accessing @mode,'','','','','',@keyfield,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL`,
        );
      res.status(200).json("data deleted successfully");
    } catch (err) {
      if (err.number === 50000) {
        // Foreign key constraint violation
        res
          .status(400)
          .json(
            "The user rights cannot be deleted due to a link with another record",
          );
        return;
      } else {
        throw err; // Rethrow other SQL errors
      }
    }
  }
};

