// Auto-generated candidate_masterLoopUpdate API for sp_candidate_master
const candidate_masterLoopUpdate = async (req, res) => {
  const candidate_masterData = req.body.candidate_masterData;

  if (!candidate_masterData || !candidate_masterData.length) {
    return res.status(400).json("Invalid or empty candidate_masterData array.");
  }

  try {
    const pool = await sql.connect(dbConfig);
    const updatedRows = [];

    for (const item of candidate_masterData) {
      const result = await pool
        .request()
        .input("mode", sql.NVarChar, "U")
        .input("candidate_name", sql.NVarChar, item.candidate_name)
        .input("email", sql.VarChar, item.email)
        .input("phone", sql.VarChar, item.phone)
        .input("applied_job_id", sql.Int, item.applied_job_id)
        .input("Education", sql.NVarChar, item.Education)
        .input("Experience", sql.NVarChar, item.Experience)
        .input("Related_experience", sql.VarChar, item.Related_experience)
        .input("Job_description", sql.VarChar, item.Job_description)
        .input("company_code", sql.VarChar, item.company_code)
        .input("keyfield", sql.VarChar, item.keyfield)
        .input("modified_by", sql.VarChar, item.modified_by)
        .query(`EXEC sp_candidate_master @mode,0,@candidate_name,@email,@phone, @applied_job_id,'',@Education,@Experience,@Related_experience,@Job_description,@company_code, @keyfield, '','','','','',@modified_by,''`);

      // 👇 capture NEW keyfield
      if (result.recordset?.length) {
        updatedRows.push({
          oldKeyfield: item.keyfield,
          newKeyfield: result.recordset[0].keyfield,
        });
      }
    }

    res.status(200).json({
      message: "candidate_master data updated successfully",
      updatedRows,
    });
  } catch (err) {
    console.error("Error in candidate_masterLoopUpdate:", err);
    res.status(500).json({ message: err.message || "Internal Server Error" });
  }
};

